// apps/web/lib/govern/data/legacy-coverage-baseline.ts
// BI-DG-002 (spec §6.1): the IMMUTABLE legacy coverage baseline. Every pre-existing
// unresolved model goes here as a whole-model gap (field "*") with an accountable
// owner, risk, remediation BI, and deadline — NEVER a blanket "internal/standard"
// classification. Whole-model granularity keeps the seal tractable and matches the
// coverage denominator by MODEL NAME only (so it cannot disagree with parsePrismaSchema
// over field enumeration); per-field classification happens as coverage waves
// (BI-DG-015+) resolve each model into the registry and DELETE its entry here.
//
// The baseline can only SHRINK (coverage.ts assertBaselineDidNotGrow). It was SEALED
// from packages/db/prisma/schema.prisma via the same model-detection regex
// parsePrismaSchema uses: 509 unresolved models (every model except the
// registered AgentMessage/data:agent-conversation). Ownership/risk are uniform at seal
// time; each wave refines them for its domain as it resolves the model.

export type LegacyCoverageRisk = "low" | "medium" | "high";

export type LegacyCoverageBaselineEntry = {
  /** Physical Prisma model that owns the unresolved gap. */
  prismaModel: string;
  /** Physical field name, or "*" for a whole-model gap. */
  field: string;
  /** Accountable owner role for resolving this gap. */
  owner: string;
  risk: LegacyCoverageRisk;
  /** Backlog item that will resolve this gap (a coverage wave, BI-DG-015+). */
  remediationBI: string;
  /** ISO date by which the gap must be resolved. */
  deadline: string;
};

export type LegacyCoverageBaseline = {
  readonly entries: readonly LegacyCoverageBaselineEntry[];
};

